def scanf():
    try:
        line = input()
        # Если строка пустая
        if not line:
            return 0

        # Если строка содержит символ новой строки
        if '\n' in line:
            # Находим индекс символа новой строки
            newline_index = line.find('\n')
            # Читаем до символа новой строки, не включая его
            content = line[:newline_index]
            # Возвращаем количество прочитанных символов
            return len(content)

        # Если строка не содержит символа новой строки, читаем всю строку
        # и возвращаем количество символов
        return len(line)

    except EOFError:
        # Если достигнут конец ввода, возвращаем -1
        return -1
    except Exception:
        # В случае любой другой ошибки ввода
        return -1

