def scan():
    try:
        # Membaca input dari stdin
        line = input()

        # Memastikan tidak lebih dari 1023 karakter
        if len(line) > 1023:
            line = line[:1023]

        # Menambahkan karakter nol di akhir (dalam Python, string sudah berakhir dengan karakter nol secara implisit)
        # Namun karena kita ingin meniru perilaku C, kita bisa mempertimbangkan string sebagai buffer
        # Dalam Python, kita tidak perlu menambahkan '\0' secara eksplisit karena string tidak memiliki terminator
        # Tapi kita akan mengembalikan jumlah karakter yang dibaca
        return len(line)

    except EOFError:
        # Jika terjadi EOF (misalnya, tidak ada input), kembalikan nilai negatif
        return -1
    except Exception:
        # Jika terjadi kesalahan lain, kembalikan nilai negatif
        return -1

