def scan():
    buffer = [''] * 1024
    index = 0
    while index < 1023:
        char = input()
        if char == '':
            break
        for c in char:
            if c == '\n':
                return index
            buffer[index] = c
            index += 1
        if char.endswith('\n'):
            return index
    return index

